class Stack:
    def __init__(self):
        self.items = []

    def push(self, item):
        if not isinstance(item, (int, float, str)):
            raise ValueError(""Invalid input: Only integers, floats, and strings are allowed."")
        self.items.append(item)

    def pop(self):
        if self.is_empty():
            raise IndexError(""Pop from empty stack"")
        return self.items.pop()

    def is_empty(self):
        return len(self.items) == 0

    def size(self):
        return len(self.items)
