def generate_html(data):
    html_content = ['<html>', '<head><title>Generated Page</title></head>', '<body>']

    for item in data:
        if 'title' in item:
            html_content.append(f""<h1>{item['title']}</h1>"")

        if 'paragraphs' in item:
            for paragraph in item['paragraphs']:
                html_content.append(f""<p>{paragraph}</p>"")

        if 'links' in item:
            for link in item['links']:
                href = link.get('href', '#')
                text = link.get('text', 'Link')
                html_content.append(f'<a href=""{href}"">{text}</a>')

    html_content.append('</body></html>')

    return '\n'.join(html_content)


# Example usage:
