    {
        ""title"": ""Welcome to My Page"",
        ""paragraphs"": [""This is an example paragraph."", ""Here's another one.""],
        ""links"": [{""href"": ""https://example.com"", ""text"": ""Example Link""}]
    },
    {
        ""title"": ""About Us"",
        ""paragraphs"": [""Learn more about what we do.""]
    }
]

html_output = generate_html(data_input)
