import hashlib

def compute_file_hash(file_path: str, chunk_size: int = 65536, hash_type: str = 'md5') -> str:
    try:
        # Select the hashing algorithm based on hash_type argument
        if hash_type == 'sha256':
            hash_obj = hashlib.sha256()
        else:
            hash_obj = hashlib.md5()

        with open(file_path, 'rb') as file:
            while chunk := file.read(chunk_size):
                hash_obj.update(chunk)

        return hash_obj.hexdigest()
    except (FileNotFoundError, IOError) as e:
        return ""Hash calculation failed""

# Example usage
md5_hash = compute_file_hash(""example.txt"")
sha256_hash = compute_file_hash(""example.txt"", hash_type='sha256')
