import requests

def fetch_user_posts(user_id):
    try:
        # Fetch users data
        users_response = requests.get('https://jsonplaceholder.typicode.com/users')
        users = {user['id']: user['name'] for user in users_response.json()}

        if user_id not in users:
            return {""error"": ""User ID does not exist.""}

        # Fetch posts data for the given user
        posts_response = requests.get(f'https://jsonplaceholder.typicode.com/posts?userId={user_id}')
        posts = sorted(posts_response.json(), key=lambda x: x['id'], reverse=True)

        return {
            ""name"": users[user_id],
            ""posts"": [post['title'] for post in posts]
        }
    except Exception as e:
        return {""error"": str(e)}

def main():
