import hashlib

def compute_string_hash(input_string: str, hash_type: str = 'md5') -> str:
    try:
        if not isinstance(input_string, str):
            raise ValueError(""Input must be a string."")

        # Choose the hashing algorithm based on the hash_type argument
        if hash_type.lower() == 'md5':
            hash_func = hashlib.md5()
        elif hash_type.lower() == 'sha256':
            hash_func = hashlib.sha256()
        else:
            raise ValueError(""Unsupported hash type. Use 'md5' or 'sha256'."")

        # Encode the input string to bytes and update the hash function
        hash_func.update(input_string.encode('utf-8'))

        # Return the hexadecimal representation of the computed hash
        return hash_func.hexdigest()

    except Exception:
        return ""Hash calculation failed""
