def process_file(file_path):
    try:
        with open(file_path, 'r') as file:
            lines = file.readlines()

        if not lines:
            raise ValueError(""File is empty"")

        # Organize lines by stripping whitespace and sorting
        organized_lines = sorted(line.strip() for line in lines)

        # Extract sequence number from the last line (assuming it's an integer)
        try:
            last_line_number = int(organized_lines[-1])
        except ValueError:
            raise ValueError(""Last line does not contain a valid integer"")

        return organized_lines, last_line_number

    except FileNotFoundError:
        raise FileNotFoundError(f""The file at {file_path} was not found."")
    except Exception as e:
        raise RuntimeError(f""An error occurred: {e}"")

