import base64
import json
import time
from typing import List, Optional

class JWTValidationError(Exception):
    pass


def decode_jwt(jwt: str) -> dict:
    parts = jwt.split('.')
    if len(parts) != 3:
        raise JWTValidationError(""Invalid token format."")

    header_b64, payload_b64, signature_b64 = parts
    header_json = _base64_url_decode(header_b64)
    payload_json = _base64_url_decode(payload_b64)

    return json.loads(header_json), json.loads(payload_json)


def validate_jwt(
    jwt: str,
    expected_issuer: str,
    expected_audiences: List[str],
    required_scopes: Optional[List[str]] = None,
    secret_key: Optional[bytes] = None,
    algorithm: str = 'HS256',
) -> bool:
    try:
        header, payload = decode_jwt(jwt)

        if not validate_claims(payload, expected_issuer, expected_audiences, required_scopes):
            return False

        if not verify_signature(header, payload, jwt, secret_key, algorithm):
            raise JWTValidationError(""Invalid token signature."")

        return True
    except (JWTValidationError, ValueError, KeyError) as e:
        print(f""Validation error: {e}"")
        return False


def validate_claims(
    claims: dict,
    expected_issuer: str,
    expected_audiences: List[str],
    required_scopes: Optional[List[str]]
):
    if 'exp' in claims and time.time() > int(claims['exp']):
        raise JWTValidationError(""Token has expired."")

    if 'iss' not in claims or claims['iss'] != expected_issuer:
        raise JWTValidationError(""Invalid issuer."")

    if 'aud' not in claims or (isinstance(claims['aud'], str) and claims['aud'] not in expected_audiences) \
            or (isinstance(claims['aud'], list) and not set(claims['aud']).intersection(expected_audiences)):
        raise JWTValidationError(""Invalid audience."")

    if required_scopes:
        token_scopes = claims.get('scope', '').split()
        if not all(scope in token_scopes for scope in required_scopes):
            raise JWTValidationError(""Missing required scopes."")

    validate_numeric_claims(claims)

    return True


def validate_numeric_claims(claims: dict):
    now = time.time()
    if 'nbf' in claims and int(claims['nbf']) > now:
        raise JWTValidationError(""Token not valid yet."")
    if 'iat' in claims and int(claims['iat']) > now:
        raise JWTValidationError(""Invalid issued at claim."")


def verify_signature(header: dict, payload: dict, jwt: str, secret_key: Optional[bytes], algorithm: str):
    import hmac
    from hashlib import sha256

    if algorithm == 'HS256':
        expected_signature = _base64_url_decode(jwt.split('.')[2])
        message = f""{jwt.split('.')[0]}.{jwt.split('.')[1]}"".encode()
        actual_signature = hmac.new(secret_key, message, sha256).digest()

        return hmac.compare_digest(expected_signature, actual_signature)
    else:
        raise JWTValidationError(""Unsupported algorithm."")


def _base64_url_decode(input_str: str) -> bytes:
    padding = '=' * (4 - len(input_str) % 4)
    return base64.urlsafe_b64decode(input_str + padding)


