import ctypes
import base64
import os

# Load the shared library containing your crypto functions
lib = ctypes.CDLL('libcrypto_functions.so')

# Define types for your C functions
lib.sha256.argtypes = [ctypes.c_char_p]
lib.sha256.restype = ctypes.c_char_p

lib.aes_128_encrypt.argtypes = [ctypes.c_char_p]
lib.aes_128_encrypt.restype = ctypes.c_char_p

class CryptoManager:
    def __init__(self):
        self.block_size = 16  # AES-128 block size in bytes
        self.padding_size = 32 - (len(os.urandom(self.block_size)) % 32)
        self.random_padding = os.urandom(self.padding_size)

    def pad_string(self, input_string: str) -> bytes:
        padding_needed = self.block_size - (len(input_string.encode('utf-8')) % self.block_size)
        if padding_needed < self.padding_size:
            padding_needed += self.padding_size - (padding_needed % self.padding_size)
        return input_string.encode('utf-8') + bytes([padding_needed]) * padding_needed + self.random_padding

    def compute_string_hash(self, input_string: str, hash_type: str = 'sha256') -> str:
        if hash_type.lower() == 'sha256':
            try:
                return base64.b64encode(lib.sha256(self.pad_string(input_string)).encode('utf-8')).decode('utf-8')
            except Exception as e:
                return ""Hash calculation failed""
        else:
            try:
                # Assuming lib.md5 is defined similarly
                return base64.b64encode(lib.md5(self.pad_string(input_string)).encode('utf-8')).decode('utf-8')
            except Exception as e:
                return ""Hash calculation failed""

    def encrypt_and_hash(self, input_data: str, key: str) -> dict:
        padded_key = (key + '\x00' * (16 - len(key) % 16)).encode('utf-8')
        encrypted_data = lib.aes_128_encrypt(padded_key + self.pad_string(input_data))

        encrypted_base64_encoded_data = base64.b64encode(encrypted_data).decode('utf-8')
        hash_value_sha256_base64_encoded_data = base64.b64encode(lib.sha256(encrypted_data)).decode('utf-8')

        return {
            'encrypted_data': encrypted_base64_encoded_data,
            'sha256_hash': hash_value_sha256_base64_encoded_data
