def extract_even_numbers(input_list):
    if not isinstance(input_list, list):
        raise TypeError(""Input must be a list"")

    def flatten(lst):
        for item in lst:
            if isinstance(item, list):
                yield from flatten(item)
            else:
                yield item

    flat_list = list(flatten(input_list))
    even_numbers = [num for num in flat_list if isinstance(num, (int, float)) and num % 2 == 0]

    return even_numbers

# Example usage
