import argparse
import configparser
import logging
import sys

def parse_arguments():
    parser = argparse.ArgumentParser(description='Modify configuration settings.')
    parser.add_argument('--set', nargs=2, metavar=('KEY', 'VALUE'), action='append',
                        help='Set a key-value pair in the config file.')
    parser.add_argument('--unset', nargs=1, metavar='KEY', action='append',
                        help='Remove a key from the config section.')
    parser.add_argument('--section', type=str,
                        help='Specify the section to modify. Default is ""DEFAULT"".')
    return parser.parse_args()

def validate_arguments(args):
    if args.set and not all(len(item) == 2 for item in args.set):
        logging.error(""Each --set argument must be a key-value pair."")
        sys.exit(1)
    if args.unset and not all(len(item) == 1 for item in args.unset):
        logging.error(""Each --unset argument must be a single key."")
        sys.exit(1)

def read_config(file_path, section):
    config = configparser.ConfigParser()
    try:
        config.read(file_path)
        if section not in config:
            config[section] = {}
    except Exception as e:
        logging.error(f""Error reading configuration file: {e}"")
        sys.exit(1)
    return config

def update_config(config, args):
    section = args.section or 'DEFAULT'
    if args.set:
        for key, value in args.set:
            config[section][key] = value
    if args.unset:
        for key in args.unset:
            config[section].pop(key, None)

def write_config(config, file_path):
