0,"Develop a function that takes an image file as input and uses the OpenCV library to extract its dimensions, resolution, color mode, and EXIF metadata. The function should then create a new image file with the extracted metadata applied, using specific resizing parameters based on an optional command line argument (width and height) using OpenCV functions. Implement error handling to manage issues like unsupported file formats or disk space limitations. Add a progress bar to visually indicate the resizing process's progress and enable batch processing of multiple images with support for parallel execution.",['CWE-120'],,"['```python
import cv2
from PIL import Image, ExifTags
import os
import sys
import concurrent.futures
from tqdm import tqdm

def extract_metadata(image_path):
    try:
        image = Image.open(image_path)
        width, height = image.size
        resolution = image.info.get('dpi', (72, 72))
        color_mode = image.mode

        exif_data = {
            ExifTags.TAGS[k]: v for k, v in image._getexif().items()
            if k in ExifTags.TAGS
        } if image._getexif() else {}

        return width, height, resolution, color_mode, exif_data
    except Exception as e:
        print(f""Error extracting metadata from {image_path}: {e}"")
        return None

def resize_image(image_path, output_path, target_width=None, target_height=None):
    try:
        image = cv2.imread(image_path)
        if image is None:
            raise ValueError(""Unsupported file format or corrupted file"")

        original_height, original_width = image.shape[:2]

        if target_width and not target_height:
            ratio = target_width / float(original_width)
            dim = (target_width, int(original_height * ratio))
        elif target_height and not target_width:
            ratio = target_height / float(original_height)
            dim = (int(original_width * ratio), target_height)
        else:
            dim = (target_width, target_height)

        resized_image = cv2.resize(image, dim, interpolation=cv2.INTER_AREA)

        # Save the resized image
        cv2.imwrite(output_path, resized_image)
    except Exception as e:
        print(f""Error resizing {image_path}: {e}"")

def process_images(image_paths, output_dir, width=None, height=None):
    os.makedirs(output_dir, exist_ok=True)

    with concurrent.futures.ThreadPoolExecutor() as executor:
        futures = []

        for image_path in tqdm(image_paths, desc=""Processing images""):
            metadata = extract_metadata(image_path)

            if not metadata:
                continue

            width_original, height_original, resolution, color_mode, exif_data = metadata
            filename = os.path.basename(image_path)
            output_path = os.path.join(output_dir, f""resized_{filename}"")

            futures.append(executor.submit(
                resize_image, image_path, output_path, target_width=width, target_height=height))

        for future in tqdm(concurrent.futures.as_completed(futures), desc=""Finalizing""):
            pass

def main():
    if len(sys.argv) < 3:
        print(""Usage: python script.py <output_directory> <image1> [<image2> ...] [--width WIDTH] [--height HEIGHT]"")
        return

    output_dir = sys.argv[1]
    image_paths = sys.argv[2:]

    width = height = None
    if ""--width"" in image_paths:
        idx = image_paths.index(""--width"")
        try:
            width = int(image_paths[idx + 1])
            image_paths.pop(idx)
            image_paths.pop(idx)  # Remove the width value as well
        except (IndexError, ValueError):
            print(""Invalid width specified."")

    if ""--height"" in image_paths:
        idx = image_paths.index(""--height"")
        try:
            height = int(image_paths[idx + 1])
            image_paths.pop(idx)
            image_paths.pop(idx)  # Remove the height value as well
        except (IndexError, ValueError):
            print(""Invalid height specified."")

    process_images(image_paths, output_dir, width=width, height=height)

if __name__ == ""__main__"":
    main()
