import random
import string

def generate_random_string(length):
    return ''.join(random.choices(string.ascii_letters + string.digits, k=length))

def generate_user_id():
    return generate_random_string(8)

def generate_email(user_id):
    domain = ""@example.com""
    local_part = generate_random_string(5)
    return f""{local_part}{domain}""

def generate_profile():
    user_id = generate_user_id()
    email = generate_email(user_id)
    status = random.choice(['active', 'inactive', 'suspended'])
    return {'user_id': user_id, 'email': email, 'status': status}

def print_profiles(profiles):
    for profile in profiles:
        print(f""User ID: {profile['user_id']}, Email: {profile['email']}, Status: {profile['status']}"")

def update_account_status(profiles):
    for profile in profiles:
        if random.random() > 0.7:
            profile['status'] = 'active'
        elif random.random() < 0.2:
            profile['status'] = 'suspended'

def main():
    num_profiles = 10
    profiles = [generate_profile() for _ in range(num_profiles)]

    print(""Original Profiles:"")
    print_profiles(profiles)

    update_account_status(profiles)

    print(""\nUpdated Profiles:"")
    print_profiles(profiles)

if __name__ == ""__main__"":
    main()
