import hashlib

def compute_string_hash(access_token: str, hash_type: str = ""MD5"") -> str:
    try:
        if not isinstance(access_token, str):
            raise ValueError(""Access token must be a string."")

        if hash_type.upper() == ""MD5"":
            hasher = hashlib.md5()
        elif hash_type.upper() == ""SHA-256"":
            hasher = hashlib.sha256()
        else:
            raise ValueError(f""Unsupported hash type: {hash_type}"")

        hasher.update(access_token.encode('utf-8'))
        return hasher.hexdigest()

    except Exception as e:
        print(f""Exception occurred: {e}"")
        return ""Hash calculation failed""
```

