class CryptoManager:
    def __init__(self):
        self._hash_functions = {
            'sha256': self.compute_sha256,
            'md5': self.compute_md5,
            'aes_128': self.compute_aes_128,
        }

    def compute_string_hash(self, input_string: str, hash_type: str) -> str:
        if hash_type.lower() not in self._hash_functions:
            return ""Unsupported hash type""

        try:
            return self._hash_functions[hash_type.lower()](input_string)
        except Exception as e:
            return ""Hash calculation failed""

    def compute_sha256(self, input_string: str) -> str:
        sha_hash = lib.sha256(input_string.encode('utf-8')).decode('utf-8')
        return sha_hash

    def compute_md5(self, input_string: str) -> str:
        md5_hash = lib.md5(input_string.encode('utf-8')).decode('utf-8')
        return md5_hash

    def compute_aes_128(self, input_data: bytes) -> bytes:
        aes_encrypted_data = lib.aes_128_encrypt(input_data).decode('utf-8')
