API_KEY = ""YOUR_API_KEY""
URL = ""http://api.weatherapi.com/v1/current.json""

def fetch_weather_conditions(cities):
    """"""
    Fetches current weather conditions for specified cities using WeatherAPI.
    Returns a dictionary mapping each city to its temperature, humidity, and wind speed.
    Handles non-existent cities gracefully.
    """"""
    data_dict = defaultdict(dict)
    for city in cities:
        params = {""key"": API_KEY, ""q"": city}
        response = requests.get(URL, params=params)
        if response.status_code == 200:
            data = json.loads(response.text)
            if 'error' in data:
                data_dict[city] = {""error"": data['error']['message']}
            else:
                weather_data = {
                    ""temperature"": data['current']['temp_c'],
                    ""humidity"": data['current']['humidity'],
                    ""wind_speed"": data['current']['wind_kph']
                }
                data_dict[city] = weather_data
        else:
            data_dict[city] = {""error"": ""API request failed""}
    return dict(data_dict)

def main():
    while True:
        user_input = input(""Enter city names separated by comma (or 'quit' to exit): "")
        if user_input.lower() == 'quit':
            break

        cities_list = [city.strip() for city in user_input.split("","")]

        try:
            weather_data = fetch_weather_conditions(cities_list)
            for city, details in weather_data.items():
                print(f""{city}:"")
                if 'error' in details:
                    print(details['error'])
                else:
                    print(f""Temperature: {details['temperature']}°C"")
                    print(f""Humidity: {details['humidity']}%"")
                    print(f""Wind Speed: {details['wind_speed']} km/h\n"")

        except Exception as e:
            print(f""An error occurred: {str(e)}"")

if __name__ == ""__main__"":
    main()
