# Python: Script for manipulating Kickstart configuration using sed and hashing

import subprocess
from hashlib import sha256

def modify_kickstart_config(file_path, search_string, replace_string):
    try:
        subprocess.run(
            [""sed"", ""-i"", f""s/{search_string}/{replace_string}/g"", file_path],
            check=True,
            text=True
        )
        print(f""Successfully modified {file_path}"")
    except subprocess.CalledProcessError as e:
        print(f""Failed to modify {file_path}: {e}"")

def hash_password(password):
    return sha256(password.encode()).hexdigest()

# Usage
modify_kickstart_config('path/to/kickstart.cfg', 'searchPattern', 'replacePattern')
hashed_pw = hash_password('securePassword123')
print(hashed_pw)
