import xml.etree.ElementTree as ET
import json

def parse_element(element):
    node = {}

    # Handle element attributes
    if element.attrib:
        node['@attributes'] = {k: v for k, v in element.attrib.items()}

    # Process child elements or text
    children = list(element)
    if children:
        processed_children = []
        for child in children:
            parsed_child = parse_element(child)
            tag = list(parsed_child.keys())[0]

            # Check if there are duplicate tags
            if tag in [list(c.keys())[0] for c in processed_children]:
                # If the existing node is not a list, convert it to one
                found = False
                for c in processed_children:
                    if list(c.keys())[0] == tag:
                        if isinstance(c[tag], list):
                            c[tag].append(parsed_child[tag])
                        else:
                            c[tag] = [c[tag], parsed_child[tag]]
                        found = True
                        break
                if not found:
                    raise Exception(f""Unexpected duplicate tag: {tag}"")
            else:
                processed_children.append(parsed_child)
        node.update({list(child.keys())[0]: list(child.values())[0] for child in processed_children})
    elif element.text and element.text.strip():
        # Handle text content
        node['#text'] = element.text.strip()

    return {element.tag: node}

def xml_to_json(xml_file, json_file):
    try:
        tree = ET.parse(xml_file)
        root = tree.getroot()

        # Parse XML into a Python dictionary
        data_dict = parse_element(root)

        # Convert dictionary to JSON
        with open(json_file, 'w') as f:
            json.dump(data_dict, f, indent=None)  # Minimize whitespace

    except ET.ParseError as e:
        print(f""Parse Error: {e}"")
    except Exception as e:
        print(f""An error occurred: {e}"")

# Debug function to display parsed nodes
def debug_print_structure(structure):
    import pprint
    pp = pprint.PrettyPrinter(indent=4)
    pp.pprint(structure)

if __name__ == ""__main__"":
    # Sample call for demonstration purposes (adjust filenames as needed)
    xml_file_path = 'config.xml'
    json_output_path = 'config.json'

    xml_to_json(xml_file_path, json_output_path)
