        import uuid
        return str(uuid.uuid4())

    def get_random_ip():
        import random
        return f""{random.randint(0, 255)}.{random.randint(0, 255)}.{random.randint(0, 255)}.{random.randint(0, 255)}""

    def get_random_port():
