import hashlib

def read_file_and_extract_sequence(file_path: str, sequence_separator: str = ':') -> tuple:
    try:
        with open(file_path, 'r') as file:
            lines = sorted(file.readlines())
            last_line = lines[-1]
            sequence_number = last_line.split(sequence_separator)[-1].strip()
            md5_hash = compute_file_hash(file_path)
    except FileNotFoundError:
        return ""File not found"", """"
    except IOError as e:
        return f""Error reading file: {e}"", """"
    else:
        return sequence_number, md5_hash

def compute_file_hash(file_path: str, chunk_size: int = 65536, hash_type='md5') -> str:
    try:
        with open(file_path, 'rb') as file:
            if hash_type == 'md5':
                hasher = hashlib.md5()
            elif hash_type == 'sha256':
                hasher = hashlib.sha256()
            else:
                raise ValueError(""Unsupported hash type"")

            while True:
                data_chunk = file.read(chunk_size)
                if not data_chunk:
                    break
                hasher.update(data_chunk)

            return hasher.hexdigest()
    except IOError as e:
        return f""Hash calculation failed: {e}""
