def calculate_total(items_dict):
    # Extract values from dictionary
    items = items_dict.get('item_list', [])
    prices = items_dict.get('prices', {})

    # Validate item list is non-empty
    if not items:
        raise ValueError(""Item list cannot be empty."")

    # Validate all items have corresponding prices
    for item in items:
        if item not in prices:
            raise ValueError(f""Missing price for item: {item}"")

    total_cost = sum(prices[item] for item in items)

    # Check for optional discount function and apply it if present
    discount_func = items_dict.get('discount_func', None)
    if callable(discount_func):
        return discount_func(total_cost)
    else:
        raise ValueError(""No valid discount function provided."")
