from Crypto.Cipher import AES
import base64

def encrypt_data(data: bytes, key: bytes, iv: bytes = None, mode: str = 'CBC') -> str:
    try:
        if len(key) not in (16, 24, 32):
            raise ValueError(""Key must be either 16, 24, or 32 bytes long."")

        if mode == 'ECB':
            cipher = AES.new(key, AES.MODE_ECB)
        elif mode == 'CBC' and iv is None:
            raise ValueError(""IV must be provided for CBC mode."")
        elif mode in ('CBC', 'CFB', 'OFB') and len(iv) != 16:
            raise ValueError(""IV must be 16 bytes long."")

        if mode == 'CBC':
            cipher = AES.new(key, AES.MODE_CBC, iv)
        elif mode == 'CTR' and iv is None:
            raise ValueError(""IV must be provided for CTR mode."")
        elif mode == 'CTR':
            cipher = AES.new(key, AES.MODE_CTR, nonce=b'', initial_value=iv)
        elif mode == 'GCM' and iv is None:
            raise ValueError(""IV must be provided for GCM mode."")
        elif mode == 'GCM':
            cipher = AES.new(key, AES.MODE_GCM, nonce=iv)

        if mode in ('CBC', 'CFB', 'OFB'):
            padded_data = data + (b'\0' * (16 - len(data) % 16))
            encrypted_data = cipher.encrypt(padded_data)
        elif mode == 'CTR':
            encrypted_data = cipher.encrypt(data)
        else:
            encrypted_data = cipher.encrypt_and_digest(data)[0]

        return base64.b64encode(encrypted_data).decode('utf-8')

    except Exception as e:
        raise ValueError(f""Encryption failed: {str(e)}"")

# Unit Tests

import unittest

class TestAESEncryption(unittest.TestCase):

    def test_valid_encryption_cbc(self):
        key = b'Sixteen byte key'
        iv = b'InitializationVe'
        data = b'Test Data'
        encrypted_data = encrypt_data(data, key, iv, 'CBC')
        self.assertIsInstance(encrypted_data, str)

    def test_invalid_key_length(self):
        with self.assertRaises(ValueError):
            encrypt_data(b'data', b'shortkey', b'iv')

    def test_missing_iv_for_cbc(self):
        with self.assertRaises(ValueError):
            encrypt_data(b'data', b'Sixteen byte key', mode='CBC')

    def test_valid_encryption_ecb(self):
        key = b'Sixteen byte key'
        data = b'Test Data'
        encrypted_data = encrypt_data(data, key, mode='ECB')
        self.assertIsInstance(encrypted_data, str)

    def test_invalid_mode(self):
        with self.assertRaises(ValueError):
            encrypt_data(b'data', b'sixteen bytes!', 'iv', 'INVALID_MODE')

    def test_gcm_encryption(self):
        key = b'Sixteen byte key'
        iv = b'InitializationV'
        data = b'Test Data'
        encrypted_data = encrypt_data(data, key, iv, 'GCM')
        self.assertIsInstance(encrypted_data, str)

if __name__ == '__main__':
