import xml.etree.ElementTree as ET
from lxml import etree

class XmlParser:
    @staticmethod
    def ParseXmlDocument(xml_file_path, xpath_query):
        try:
            tree = etree.parse(xml_file_path)
            nodes = tree.xpath(xpath_query)

            if len(nodes) != 1:
                raise Exception(""XPath query did not return exactly one node."")

            node = nodes[0]
            attributes_and_text = {}
            for attr in node.attrib.keys():
                id_value = node.get(attr)
                inner_text = node.text.strip() if node.text else """"
                attributes_and_text[id_value] = inner_text

            return attributes_and_text

        except Exception as e:
            raise Exception(f""Error parsing XML: {e}"")

class BinaryFileProcessor:
    @staticmethod
    def ProcessBinaryFile(binary_file_path, ruleset):
        processed_data = []

        try:
            with open(binary_file_path, 'rb') as file:
                binary_content = file.read()

            for index, (start, end) in enumerate(ruleset):
                position = start
                while position < end and position + 1 < len(binary_content):
                    byte_pair = binary_content[position:position+2]

                    if len(byte_pair) == 2:
                        character = chr(int.from_bytes(byte_pair, 'big'))
                        processed_data.append((index, character))

                    position += 2

            return processed_data

        except Exception as e:
            raise Exception(f""Error processing binary file: {e}"")
