import random

class PDNAddress:
    def __init__(self, pti, ipv4=None, ipv6=None):
        self.pti = pti  # Protocol Type Identifier
        self.ipv4 = ipv4
        self.ipv6 = ipv6

    def is_valid(self):
        return (self.pti in [1, 2] and 
                ((self.pti == 1 and isinstance(self.ipv4, str) and self._is_valid_ipv4(self.ipv4)) or 
                 (self.pti == 2 and isinstance(self.ipv6, str) and self._is_valid_ipv6(self.ipv6))))

    @staticmethod
    def _is_valid_ipv4(ipv4):
        parts = ipv4.split('.')
        return len(parts) == 4 and all(part.isdigit() and 0 <= int(part) < 256 for part in parts)

    @staticmethod
    def _is_valid_ipv6(ipv6):
        import re
        pattern = re.compile(r'^([\da-fA-F]{1,4}:){7}[\da-fA-F]{1,4}$')
        return bool(pattern.match(ipv6))

class UEAddress:
    def __init__(self, pti, ipv4=None, ipv6=None):
        self.pti = pti  # Protocol Type Identifier
        self.ipv4 = ipv4
        self.ipv6 = ipv6

    def is_valid(self):
        return (self.pti in [1, 2] and 
                ((self.pti == 1 and isinstance(self.ipv4, str) and PDNAddress._is_valid_ipv4(self.ipv4)) or 
                 (self.pti == 2 and isinstance(self.ipv6, str) and PDNAddress._is_valid_ipv6(self.ipv6))))

class MMEContextUpdateMessage:
    def __init__(self, pdn_address, ue_address, context_accept_reject_indicator):
        self.pdn_address = pdn_address
        self.ue_address = ue_address
        self.context_accept_reject_indicator = context_accept_reject_indicator

def generate_mme_context_update_messages(count):
    messages = []

    for _ in range(count):
        # Randomly create PDNAddress
        pti = random.choice([1, 2])
        if pti == 1:
            ipv4_address = f""{random.randint(0, 255)}.{random.randint(0, 255)}."" \
                           f""{random.randint(0, 255)}.{random.randint(0, 255)}""
            pdn_address = PDNAddress(pti=pti, ipv4=ipv4_address)
        else:
            ipv6_address = ':'.join(f'{random.randint(0, 65535):x}' for _ in range(8))
            pdn_address = PDNAddress(pti=pti, ipv6=ipv6_address)

        # Randomly create UEAddress
        pti = random.choice([1, 2])
        if pti == 1:
            ue_ipv4_address = f""{random.randint(0, 255)}.{random.randint(0, 255)}."" \
                              f""{random.randint(0, 255)}.{random.randint(0, 255)}""
            ue_address = UEAddress(pti=pti, ipv4=ue_ipv4_address)
        else:
            ue_ipv6_address = ':'.join(f'{random.randint(0, 65535):x}' for _ in range(8))
            ue_address = UEAddress(pti=pti, ipv6=ue_ipv6_address)

        # Randomly set contextAcceptRejectIndicator
        context_accept_reject_indicator = random.choice([True, False])

        if pdn_address.is_valid() and ue_address.is_valid():
            messages.append(MMEContextUpdateMessage(pdn_address, ue_address, context_accept_reject_indicator))

    return messages

# Example usage:
messages = generate_mme_context_update_messages(5)
for msg in messages:
    print(vars(msg.pdn_address), vars(msg.ue_address), msg.context_accept_reject_indicator)
```']",247,[0],[],True,0,0,0,

