def fetch_weather_conditions(cities):
    """"""
    Fetches current weather conditions for specified cities using WeatherAPI.
    Returns a dictionary mapping each city to its temperature, humidity, and wind speed.
    Handles non-existent cities gracefully.
    """"""
    data_dict = defaultdict(dict)
