            data = json.loads(response.text)
            if 'error' in data:
                data_dict[city] = {""error"": data['error']['message']}
            else:
                weather_data = {
                    ""temperature"": data['current']['temp_c'],
                    ""humidity"": data['current']['humidity'],
                    ""wind_speed"": data['current']['wind_kph']
                }
                data_dict[city] = weather_data
