import multiprocessing as mp
import random
import time
from queue import Empty

class JobTask:
    def __init__(self, tag: int = None):
        self.tag = tag or random.randint(10000000, 99999999)
        self.rnti = random.randint(12345678, 87654321)
        self.crc_tag = {
            ""CRC_INDICATION_REL8_TAG"": random.randint(
                12345678901234567890,
                98765432109876543210
            ),
            ""CRCFLAG"": True
        }

class NFAPI_CRC_INDICATION_PDU_T:
    def __init__(self, task: JobTask):
        self.RX_UE_INFORMATION_TAG = f""RX{task.tag}""
        self.RNTI = str(task.rnti)
        self.CRC_INDICATION_REL8_TAG = task.crc_tag

def generate_job_tasks(n_tasks: int) -> list[JobTask]:
    return [JobTask() for _ in range(n_tasks)]

def process_task(task_id, task_data):
    print(f""Processing Task {task_id}"")
    pdu_struct = NFAPI_CRC_INDICATION_PDU_T(task_data)
    # Simulate processing time
    time.sleep(random.uniform(0.1, 0.5))
    return f""Processed PDU with RX_TAG: {pdu_struct.RX_UE_INFORMATION_TAG}""

def worker(tasks_queue, results_queue):
    while True:
        try:
            task_id, task_data = tasks_queue.get(timeout=3)
            result = process_task(task_id, task_data)
            results_queue.put(result)
        except Empty:
            break

def main(n_tasks: int):
    manager = mp.Manager()
    tasks_queue = manager.Queue()
    results_queue = manager.Queue()

    # Generate and enqueue job tasks
    for i in range(n_tasks):
        tasks_queue.put((i, generate_job_tasks(1)[0]))

    processes = []
    num_workers = min(mp.cpu_count(), n_tasks)

    # Start worker processes
    for _ in range(num_workers):
        p = mp.Process(target=worker, args=(tasks_queue, results_queue))
        processes.append(p)
        p.start()

    try:
        # Collect results
        while any(p.is_alive() for p in processes):
            while not results_queue.empty():
                print(results_queue.get())
            time.sleep(0.1)  # Short sleep to reduce busy-waiting

    except KeyboardInterrupt:
        print(""Interrupted by user"")

    finally:
        # Gracefully shutdown
        for _ in range(num_workers):
            tasks_queue.put((None, None))  # Send poison pill

        for p in processes:
            p.join()

