import argparse
import os

def summarize_file(file_path):
    try:
        with open(file_path, 'r') as f:
            content = f.read()
            lines = content.splitlines()
            words = content.split()
            num_lines = len(lines)
            num_words = len(words)
            num_chars = len(content)

        return {
            ""total_characters"": num_chars,
            ""total_words"": num_words,
            ""total_lines"": num_lines
        }
    except Exception as e:
        print(f""Error summarizing file: {e}"")
        raise

def count_unique_words(file_path):
    try:
        with open(file_path, 'r') as f:
            words = set(f.read().split())

        return len(words)
    except Exception as e:
        print(f""Error counting unique words: {e}"")
        raise

def write_output(output_file, data, message):
    if os.path.exists(output_file):
        raise FileExistsError(f""The output file '{output_file}' already exists."")

    with open(output_file, 'w') as f:
        f.write(message + ""\n"")
        for key, value in data.items():
            f.write(f""{key}: {value}\n"")

def main():
    parser = argparse.ArgumentParser(description=""Process a file to summarize or count unique words."")
    parser.add_argument('file', type=str, help='The input file to process.')
    parser.add_argument('-s', '--summarize', action='store_true', help='Summarize the file content.')
    parser.add_argument('-l', '--unique_words', action='store_true', help='Count unique words in the file.')
    parser.add_argument('-o', '--output', type=str, help='Output results to a specified file.')

    args = parser.parse_args()

    if not os.path.exists(args.file):
        print(f""Error: The file '{args.file}' does not exist."")
        return

    try:
        if args.summarize and args.unique_words:
            print(""Error: Please choose only one functionality (-s or -l)."")
            return
        elif args.summarize:
            summary = summarize_file(args.file)
            output_message = ""File Summary:\n""
            result_data = summary

        elif args.unique_words:
            unique_word_count = count_unique_words(args.file)
            output_message = f""Unique Word Count: {unique_word_count}\n""
            result_data = {""unique_word_count"": unique_word_count}

        if args.output:
            write_output(args.output, result_data, output_message)
            print(f""Results have been written to '{args.output}'."")
        else:
            if isinstance(result_data, dict):
                for key, value in result_data.items():
                    print(f""{key}: {value}"")
            else:
                print(output_message)

    except FileExistsError as e:
        print(e)

if __name__ == ""__main__"":
    main()
