import json
import logging

# Configure logging
logging.basicConfig(level=logging.ERROR, format='%(asctime)s - %(levelname)s - %(message)s')

class Graph:
    def __init__(self):
        self.nodes = {}
        self.edges = []

def load_graph_from_file(file_path):
    graph = Graph()

    try:
        with open(file_path, 'r') as file:
            data = json.load(file)

        # Validate required fields
        if 'nodes' not in data or 'edges' not in data:
            logging.error(""Graph serialization is missing 'nodes' or 'edges'."")
            return None

        nodes = data['nodes']
        edges = data['edges']

        # Load nodes
        for node_id, node_data in nodes.items():
            graph.nodes[node_id] = node_data

        # Validate and load edges
        if not isinstance(edges, list):
            logging.error(""Graph serialization 'edges' is not a list."")
            return None

        for edge in edges:
            if not (isinstance(edge, tuple) and len(edge) == 2):
                logging.error(f""Invalid edge format: {edge}. Expected tuple of length 2."")
                continue
            graph.edges.append(edge)

    except FileNotFoundError:
        logging.error(f""File not found: {file_path}"")
    except json.JSONDecodeError as e:
        logging.error(f""JSON decoding error in file {file_path}: {e.msg}"")
    except Exception as e:
        logging.error(f""Unexpected error while loading graph from file {file_path}: {str(e)}"")

    return graph

# Example usage
graph = load_graph_from_file('path_to_your_file.json')
