# models.py

from django.db import models
import uuid
from django.contrib.auth.models import AbstractUser
from django.utils.translation import gettext_lazy as _

class User(AbstractUser):
    email_verified = models.BooleanField(default=False)
    verification_token = models.UUIDField(null=True, blank=True)

class ActivationToken(models.Model):
    user = models.ForeignKey(User, on_delete=models.CASCADE)
    token = models.UUIDField(default=uuid.uuid4, editable=False, unique=True)
    created_at = models.DateTimeField(auto_now_add=True)
    used = models.BooleanField(default=False)


# views.py

from django.shortcuts import render
from rest_framework.views import APIView
from rest_framework.response import Response
from .models import User, ActivationToken
from .services import UserService
import uuid
from django.core.mail import send_mail


class RegisterAPIView(APIView):
    def post(self, request, *args, **kwargs):
        # Get data from request to create user
        username = request.data.get('username')
        email = request.data.get('email')
        password = request.data.get('password')

        if not UserService.is_password_strong(password):
            return Response({""error"": ""Password is not strong enough.""}, status=400)

        user, created = User.objects.update_or_create(
            username=username,
            defaults={""email"": email}
        )

        verification_token = uuid.uuid4()
        user.verification_token = verification_token
        user.save()

        # Send verification email
        send_mail(
            'Verify your account',
            f'Your verification token is {verification_token}',
            'from@example.com',
            [user.email],
            fail_silently=False,
        )

        return Response({""message"": ""User registered. Please check your email to verify.""}, status=201)


class VerifyEmailAPIView(APIView):
    def get(self, request, *args, **kwargs):
        token = kwargs.get('token')
        user = User.objects.filter(verification_token=token).first()

        if not user:
            return Response({""error"": ""Invalid verification token.""}, status=400)

        user.email_verified = True
        user.verification_token = None
        user.save()

        return Response({""message"": ""Email verified successfully.""})


class ActivateAccountAPIView(APIView):
    def post(self, request, *args, **kwargs):
        token = request.data.get('token')
        activation_token = ActivationToken.objects.filter(token=token).first()

        if not activation_token or activation_token.used:
            return Response({""error"": ""Invalid or already used activation token.""}, status=400)

        user = activation_token.user
        # Perform account activation logic here

        activation_token.used = True
        activation_token.save()

        return Response({""message"": ""Account activated successfully.""})


class CustomPasswordCheckAPIView(APIView):
    def get(self, request, *args, **kwargs):
        password = request.query_params.get('password')

        if not UserService.is_password_strong(password):
            return Response({""error"": ""Password does not meet strength requirements.""}, status=400)

        return Response({""message"": ""Password is strong.""})


# services.py

import re
from .models import User


class UserService:
    @staticmethod
    def is_password_strong(password):
        # Custom logic for password strength
        if len(password) < 8:
            return False
        if not re.search(r'\d', password):
            return False
        if not re.search(r'[A-Z]', password):
            return False
        if not re.search(r'[a-z]', password):
            return False
        if not re.search(r'[\W_]', password):
            return False

        # Check against user's past passwords (pseudo-implementation)
        user = User.objects.filter(past_passwords=password).exists()

        return not user


# urls.py

from django.urls import path
from .views import RegisterAPIView, VerifyEmailAPIView, ActivateAccountAPIView, CustomPasswordCheckAPIView

urlpatterns = [
    path('register/', RegisterAPIView.as_view(), name='register'),
    path('verify-email/<uuid:token>/', VerifyEmailAPIView.as_view(), name='verify_email'),
    path('activate-account/', ActivateAccountAPIView.as_view(), name='activate_account'),
    path('check-password/', CustomPasswordCheckAPIView.as_view(), name='check_password'),
]
