import cv2
import os
import piexif
from tqdm import tqdm
import concurrent.futures

def get_image_metadata(image_path):
    try:
        # Load image using OpenCV
        img = cv2.imread(image_path)
        if img is None:
            raise ValueError(""Unsupported file format or corrupted image"")

        height, width, channels = img.shape

        # Get EXIF data using piexif
        exif_data = {}
        if os.path.splitext(image_path)[1].lower() in ['.jpg', '.jpeg']:
            try:
                exif_dict = piexif.load(image_path)
                exif_data = {piexif.TAGS[k][0]: v for k, v in exif_dict[""Exif""].items()}
            except Exception as e:
                print(f""Error reading EXIF data: {e}"")

        # Determine color scheme
        if channels == 1:
            color_scheme = ""Grayscale""
        elif channels == 3:
            color_scheme = ""RGB""
        elif channels == 4:
            color_scheme = ""RGBA""
        else:
            color_scheme = ""Unknown""

        return {
            'dimensions': (width, height),
            'resolution': cv2.imread(image_path, cv2.IMREAD_ANYDEPTH | cv2.IMREAD_ANYCOLOR).shape[:2],
            'color_scheme': color_scheme,
            'exif_data': exif_data
        }
    except Exception as e:
        print(f""Error processing image {image_path}: {e}"")
        return None

def resize_image(image_path, output_path, width=None, height=None):
    try:
        img = cv2.imread(image_path)
        if img is None:
            raise ValueError(""Unsupported file format or corrupted image"")

        original_height, original_width = img.shape[:2]

        # Calculate new dimensions
        if width and not height:
            scale_ratio = width / float(original_width)
            dim = (width, int(original_height * scale_ratio))
        elif height and not width:
            scale_ratio = height / float(original_height)
            dim = (int(original_width * scale_ratio), height)
        else:
            dim = (width or original_width, height or original_height)

        # Resize with progress bar
        resized_img = cv2.resize(img, dim, interpolation=cv2.INTER_AREA)

        for i in tqdm(range(10), desc=""Resizing Progress""):
            pass  # Simulate resizing steps

        # Save the resized image
        if not os.path.exists(os.path.dirname(output_path)):
            os.makedirs(os.path.dirname(output_path))
        cv2.imwrite(output_path, resized_img)
    except Exception as e:
        print(f""Error resizing image {image_path}: {e}"")

def process_image(image_path, output_folder, width=None, height=None):
    metadata = get_image_metadata(image_path)

    if not metadata:
        return

    # Create output path with metadata
    base_name = os.path.basename(image_path)
    new_name = f""{os.path.splitext(base_name)[0]}_metadata.jpg""
    output_path = os.path.join(output_folder, new_name)

    resize_image(image_path, output_path, width, height)

def batch_process_images(input_folder, output_folder, width=None, height=None):
    image_files = [f for f in os.listdir(input_folder) if os.path.isfile(os.path.join(input_folder, f))]

    with concurrent.futures.ThreadPoolExecutor() as executor:
        futures = [
            executor.submit(process_image, os.path.join(input_folder, file), output_folder, width, height)
            for file in image_files
        ]

        for future in tqdm(concurrent.futures.as_completed(futures), total=len(image_files), desc=""Processing Images""):
            try:
                future.result()
            except Exception as e:
                print(f""Error in batch processing: {e}"")

# Example usage (assuming command-line arguments for width and height are parsed separately):
