import random

def generate_random_tcp_connections(num_connections):
    def random_ip():
        return '.'.join(str(random.randint(0, 255)) for _ in range(4))

    def random_port():
        return random.randint(1024, 65535)

    connection_states = ['ESTABLISHED', 'SYN_SENT', 'SYN_RECV', 'FIN_WAIT_1']

    connections = []
    for _ in range(num_connections):
        connection = {
            'source_ip': random_ip(),
            'destination_ip': random_ip(),
            'source_port': random_port(),
            'destination_port': random_port(),
            'connection_state': random.choice(connection_states)
        }
        connections.append(connection)

    return connections

# Example usage:
connections = generate_random_tcp_connections(5)
for conn in connections:
    print(conn)
