from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.backends import default_backend
import os

def create_cipher_instance(cipher_name: str):
    try:
        if cipher_name == ""AES-GCM"":
            key = os.urandom(16)  # Generate a random 128-bit (16-byte) key
            algorithm = algorithms.AES(key)
            mode = modes.GCM(os.urandom(12))  # Generate a random nonce for GCM
            return Cipher(algorithm, mode, backend=default_backend())
        elif cipher_name == ""AES-CFB"":
            key = os.urandom(16)  # Generate a random 128-bit (16-byte) key
            iv = os.urandom(16)   # Generate a random 16-byte IV for CFB
            algorithm = algorithms.AES(key)
            mode = modes.CFB(iv)
            return Cipher(algorithm, mode, backend=default_backend())
        else:
            return None
    except Exception as e:
        return None
