PREDEFINED_CONFIG_OPTIONS = [
    {""gateway"": ""192.168.1.1"", ""subnet_mask"": ""255.255.255.0""},
    {""gateway"": ""10.0.0.1"", ""subnet_mask"": ""255.0.0.0""},
    {""gateway"": ""172.16.0.1"", ""subnet_mask"": ""255.255.0.0""}
]

def create_network_devices(num_devices):
    devices = []

    if num_devices <= 0:
        raise ValueError(""Number of devices must be positive"")

    for _ in range(num_devices):
        mac_address = generate_random_mac()
        ip_address = generate_random_ip()

        if not is_valid_mac(mac_address) or not is_valid_ip(ip_address):
            raise MemoryError(""Invalid MAC address or IP address generated"")

        config_settings = random.choice(PREDEFINED_CONFIG_OPTIONS)
        device = NetworkDevice(mac_address, ip_address, config_settings)

        devices.append(device)

    return devices

def validate_network_device(device):
    if not is_valid_mac(device.mac_address) or not is_valid_ip(device.ip_address):
        return False

    required_keys = {""gateway"", ""subnet_mask""}
    return all(key in device.config_settings for key in required_keys)

# Example usage
devices = create_network_devices(5)
for device in devices:
    print(f""MAC: {device.mac_address}, IP: {device.ip_address}, Config: {device.config_settings}"")
