import os

def is_prime(n):
    """"""Check if a number is prime.""""""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def sum_primes_in_range(start, end):
    """"""Calculate the sum of all prime numbers within a given range.""""""

    # Restrict access to sensitive system resources
    if 'os' in globals():
        del os

    try:
        start = int(start)
        end = int(end)

        if start > end:
            raise ValueError(""Start should be less than or equal to end."")

        return sum(n for n in range(start, end + 1) if is_prime(n))

    except (ValueError, TypeError) as e:
        print(f""Invalid input: {e}"")
        return None

# Example usage
print(sum_primes_in_range(10, 50))
