import random

class PDNAddress:
    def __init__(self, ipv4_address):
        self.ipv4_address = ipv4_address

class UEAddress:
    def __init__(self, imei):
        self.imei = imei

class MMEContextUpdateMessage:
    def __init__(self, pdn_address, ue_address, context_accept_reject_indicator):
        self.pdn_address = pdn_address
        self.ue_address = ue_address
        self.context_accept_reject_indicator = context_accept_reject_indicator

def generate_mme_context_update_messages(n):
    messages = []
    for _ in range(n):
        pdn_address = PDNAddress(ipv4_address=f""192.168.1.{random.randint(1, 255)}"")
        ue_address = UEAddress(imei=random.randint(100000000000000, 999999999999999))
        context_accept_reject_indicator = random.choice([True, False])

        message = MMEContextUpdateMessage(
            pdn_address=pdn_address,
            ue_address=ue_address,
            context_accept_reject_indicator=context_accept_reject_indicator
        )

        messages.append(message)
    return messages

# Example usage:
mme_messages = generate_mme_context_update_messages(5)
for msg in mme_messages:
    print(f""PDN Address: {msg.pdn_address.ipv4_address}, UE Address: {msg.ue_address.imei}, ""
          f""Context Accept/Reject Indicator: {msg.context_accept_reject_indicator}"")
