import random

class Node:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

def build_bst(max_nodes, node_values):
    if not node_values or len(node_values) > max_nodes:
        return None

    node_values.sort()

    def insert_into_bst(start, end):
        if start > end:
            return None

        mid = (start + end) // 2
        node = Node(node_values[mid])

        node.left = insert_into_bst(start, mid - 1)
        node.right = insert_into_bst(mid + 1, end)

        return node

    return insert_into_bst(0, len(node_values) - 1)

class CRCIndicationRel8Tag:
    def __init__(self):
        self.crcflag = None

class NFAPI_CRC_INDICATION_PDU_T:
    def __init__(self):
        self.rx_ue_information_tag = """"
        self.rnti = None
        self.crc_indication_rel8_tag = CRCIndicationRel8Tag()

def create_bst_with_nfaapi_data(max_nodes, node_values, num_pdu_structures):
    if not node_values or max_nodes <= 0 or num_pdu_structures <= 0:
        return None

    bst_root = build_bst(max_nodes, node_values)

    crc_ind_list = [NFAPI_CRC_INDICATION_PDU_T() for _ in range(num_pdu_structures)]

    for i in range(num_pdu_structures):
        crc_ind_list[i].rx_ue_information_tag = ""tag_"" + str(i)
        crc_ind_list[i].rnti = random.randint(0, 999)
        crc_ind_list[i].crc_indication_rel8_tag.crcflag = random.randint(0, 1) == 1

    return bst_root, crc_ind_list
