def calculate_total_cost(items_dict, discount_func=None):
    # Ensure item list is not empty
    if not isinstance(items_dict, dict) or 'items' not in items_dict or not items_dict['items']:
        raise ValueError(""Item list must be provided and cannot be empty."")

    # Check for the presence of prices and match with items
    if 'prices' not in items_dict or len(items_dict['items']) != len(items_dict['prices']):
        raise ValueError(""Each item must have a corresponding price."")

    # Calculate total cost without discount
    total_cost = sum(price for price in items_dict['prices'])

    # Apply discount function if provided
    if discount_func and callable(discount_func):
        return discount_func(total_cost)
    elif not discount_func:
        raise ValueError(""A valid discount function must be supplied to compute the discounted cost."")

    return total_cost

# Example usage:
items = {
    'items': ['apple', 'banana'],
    'prices': [1.0, 2.0]
}

def discount_10_percent(total):
    return total * 0.9

try:
    print(calculate_total_cost(items, discount_func=discount_10_percent))
except ValueError as e:
    print(e)
