import random
import string

class Graph:
    def __init__(self):
        self.vertices = {}
        self.edges = []

    def add_vertex(self, vertex_id, properties):
        if vertex_id not in self.vertices:
            self.vertices[vertex_id] = properties

    def add_edge(self, from_vertex, to_vertex):
        edge = (from_vertex, to_vertex)
        if edge not in self.edges:
            self.edges.append(edge)

def generate_unique_id(length=8):
    return ''.join(random.choices(string.ascii_letters + string.digits, k=length))

def add_random_elements(graph):
    num_vertices = random.randint(1, 10)
    vertices_added = set()

    for _ in range(num_vertices):
        vertex_id = generate_unique_id()
        properties = {f'prop_{i}': random.random() for i in range(random.randint(1, 5))}

        graph.add_vertex(vertex_id, properties)
        vertices_added.add(vertex_id)

        # Connect to other existing vertices
        if len(vertices_added) > 1:
            for _ in range(random.randint(0, 3)):
                other_vertex = random.choice(list(vertices_added - {vertex_id}))
                graph.add_edge(vertex_id, other_vertex)

