import threading
import logging
import ipaddress
from Crypto.Cipher import AES
from hashlib import sha256
import os
import random
import time

# Configure logging
logging.basicConfig(level=logging.DEBUG, format='%(asctime)s - %(levelname)s - %(message)s')

def validate_ip_address(ip):
    try:
        return str(ipaddress.ip_address(ip))
    except ValueError:
        raise ValueError(""Invalid IP address"")

def generate_packet_id():
    return random.randint(1000, 9999)

def generate_timestamp():
    return time.time()

def create_sequence_number():
    return random.randint(1, 65535)

def calculate_checksum(data):
    # Simple checksum calculation
    return sha256(data).hexdigest()[:8]

def encrypt_data(data, key):
    cipher = AES.new(key, AES.MODE_EAX)
    nonce = cipher.nonce
    ciphertext, tag = cipher.encrypt_and_digest(data)
    return nonce + ciphertext

def decrypt_data(encrypted_data, key):
    nonce = encrypted_data[:16]
    ciphertext = encrypted_data[16:]
    cipher = AES.new(key, AES.MODE_EAX, nonce=nonce)
    data = cipher.decrypt(ciphertext)
    return data

def generate_packet(ip_version, payload_size, encryption_status, packet_id, timestamp, sequence_number, checksum):
    # Construct the packet
    ip_protocol_version = 'IPv4' if ip_version == 4 else 'IPv6'
    logging.info(f""Packet created: {ip_protocol_version}, Payload Size: {payload_size} bytes, Encrypted: {encryption_status}"")
    return {
        ""id"": packet_id,
        ""timestamp"": timestamp,
        ""sequence_number"": sequence_number,
        ""checksum"": checksum,
        ""ip_protocol_version"": ip_protocol_version,
        ""payload_size"": payload_size,
        ""encryption_status"": encryption_status
    }

def packet_worker(ip, packet_count, key, results):
    for _ in range(packet_count):
        try:
            ip_version = 4 if ':' not in ip else 6
            validated_ip = validate_ip_address(ip)

            packet_id = generate_packet_id()
            timestamp = generate_timestamp()
            sequence_number = create_sequence_number()

            payload = os.urandom(random.randint(64, 1024))  # Random payload size between 64 and 1024 bytes
            encrypted_payload = encrypt_data(payload, key) if encryption_status else payload

            checksum = calculate_checksum(encrypted_payload)

            packet = generate_packet(ip_version, len(encrypted_payload), bool(encryption_status), packet_id, timestamp, sequence_number, checksum)
            results.append(packet)

        except Exception as e:
            logging.error(f""Error generating packet: {e}"")

def network_packet_generator(destination_ip, num_packets, encryption_enabled=True):
    if not isinstance(num_packets, int) or num_packets <= 0:
        raise ValueError(""Number of packets must be a positive integer"")

    key = os.urandom(32)  # AES-256 key
    results = []

    try:
        threads = []
        num_threads = min(num_packets, 10)
        packets_per_thread = num_packets // num_threads

        for _ in range(num_threads):
            thread = threading.Thread(target=packet_worker, args=(destination_ip, packets_per_thread, key, results))
            threads.append(thread)
            thread.start()

        # Handle any remaining packets
        remaining_packets = num_packets % num_threads
        if remaining_packets:
            packet_worker(destination_ip, remaining_packets, key, results)

        for thread in threads:
            thread.join()

    except MemoryError as mem_err:
        logging.critical(f""Memory allocation error: {mem_err}"")
    except Exception as e:
        logging.error(f""An unexpected error occurred: {e}"")

    return results

# Example usage
if __name__ == ""__main__"":
    packets = network_packet_generator(""192.168.1.1"", 100)
    for packet in packets[:5]:  # Print first 5 packets for brevity
        print(packet)
