import requests

def get_stock_data(symbol):
    api_key = ""YOUR_ALPHA_VANTAGE_API_KEY""
    base_url = f""https://www.alphavantage.co/query?function=OVERVIEW&symbol={symbol}&apikey={api_key}""

    try:
        response = requests.get(base_url)
        response.raise_for_status()
        data = response.json()

        if ""Error Message"" in data:
            return {symbol: ""Invalid symbol or API error""}

        latest_price = float(data.get(""Latest Price"", ""N/A""))
        volume = int(data.get(""Volume"", 0))
        market_cap = int(data.get(""Market Capitalization"", 0).replace("","", """"))

        return {
            symbol: {
                ""latest_price"": latest_price,
                ""volume"": volume,
                ""market_cap"": market_cap
            }
        }

    except requests.exceptions.RequestException as e:
        return {symbol: f""API request error: {e}""}

def main():
    while True:
        user_input = input(""Enter company symbols separated by commas (or 'quit' to exit): "")

        if user_input.lower() == ""quit"":
            break

        symbols = [s.strip() for s in user_input.split("","")]

        try:
            stock_data = {}
            for symbol in symbols:
                data = get_stock_data(symbol)
                stock_data.update(data)

            print(stock_data)

        except Exception as e:
            print(f""An error occurred: {e}"")

if __name__ == ""__main__"":
    main()
