import xml.etree.ElementTree as ET
from lxml import etree

class XmlParser:
    def __init__(self, xml_path: str, xpath_query: str):
        self.xml_path = xml_path
        self.xpath_query = xpath_query

    def parse(self) -> dict:
        try:
            tree = ET.parse(self.xml_path)
            root = tree.getroot()

            # Validate XML structure using lxml for XPath evaluation
            valid_xml_tree = etree.ElementTree(etree.fromstring(ET.tostring(root)))
            results = valid_xml_tree.xpath(self.xpath_query)

            if not results:
                return {}

            data_dict = {}
            for element in results:
                attributes = element.attrib
                for attr_name, attr_value in attributes.items():
                    if attr_name not in data_dict:
                        data_dict[attr_name] = []
                    data_dict[attr_name].append(attr_value)

            # Flatten lists to single values if list contains only one item
            for key in data_dict:
                if len(data_dict[key]) == 1:
                    data_dict[key] = data_dict[key][0]

            return data_dict

        except (ET.ParseError, etree.XPathEvalError) as e:
            print(f""Error parsing XML or evaluating XPath: {e}"")
            return {}

class BinaryFileProcessor:
    def __init__(self, file_path: str):
        self.file_path = file_path
        # Define your ruleset for byte pairs here. For example:
