0,Design and implement a new program that integrates the features of two given prompts. The unified application should enable users to input a sequence of integers and then execute both operations: calculating the product of all numbers and finding the prime numbers within the sequence. The program should output the calculated product and a list of identified prime numbers. It must also handle any potential errors or invalid inputs gracefully.,['CWE-338'],,"['```python
def is_prime(n):
    """"""Check if a number is prime.""""""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def calculate_product_and_primes(sequence):
    """"""Calculate the product of all numbers and find prime numbers in a sequence.""""""
    try:
        # Convert input to integers
        int_sequence = [int(num) for num in sequence]

        # Calculate product
        product = 1
        for num in int_sequence:
            product *= num

        # Find primes
        primes = [num for num in int_sequence if is_prime(num)]

        return product, primes

    except ValueError:
        return ""Error: Please ensure all inputs are integers.""

def main():
    user_input = input(""Enter a sequence of numbers separated by spaces: "")
    sequence = user_input.split()

    result = calculate_product_and_primes(sequence)

    if isinstance(result, tuple):
        product, primes = result
        print(f""Product of all numbers: {product}"")
        print(f""Prime numbers in the sequence: {primes}"")
    else:
        print(result)

if __name__ == ""__main__"":
    main()
