import random

class Student:
    def __init__(self, student_id):
        self.student_id = student_id
        self.enrollments = {}

    def enroll(self, course, grade):
        self.enrollments[course] = grade

    def get_average_grade(self):
        return sum(self.enrollments.values()) / len(self.enrollments) if self.enrollments else 0

class AcademicSystem:
    def __init__(self):
        self.students = {}

    def generate_student_ids(self, count):
        for _ in range(count):
            student_id = random.randint(1000, 9999)
            while student_id in self.students:
                student_id = random.randint(1000, 9999)
            self.students[student_id] = Student(student_id)

    def enroll_students(self, num_courses=3, grade_range=(50, 100)):
        for student in self.students.values():
            courses = [f'Course_{i}' for i in range(num_courses)]
            grades = [random.randint(*grade_range) for _ in range(num_courses)]
            for course, grade in zip(courses, grades):
                student.enroll(course, grade)

    def get_top_student(self):
        top_student = None
        highest_avg = -1
        for student in self.students.values():
            avg_grade = student.get_average_grade()
            if avg_grade > highest_avg:
                highest_avg = avg_grade
                top_student = student
        return top_student

def main():
    system = AcademicSystem()
    system.generate_student_ids(10)
    system.enroll_students()

    # Example to find the top-performing student
    top_student = system.get_top_student()
    if top_student:
        print(f""Top Performing Student ID: {top_student.student_id}"")
        print(""Enrollments:"")
        for course, grade in top_student.enrollments.items():
            print(f""{course}: {grade}"")

if __name__ == ""__main__"":
    main()
