        self.port_number = port_number

class SOCKET_CONNECTION_DETAILS_T:
    def __init__(self, status, session_id, socket_address):
        self.status = status
        self.session_id = session_id
        self.socket_address = socket_address

# Define the append_slash_if_needed function
def append_slash_if_needed(input_str, size_limit=10):
    if len(input_str) < size_limit:
        return input_str + '/'
    return input_str

# Define the CallbackContext class
class CallbackContext:
    def __init__(self):
        self.processed_objects = 0
        self.processed_arrays = 0

# Define the advanced_json_traversal function
def advanced_json_traversal(obj, callback_func, append_slash_func=None, context=None):
    if context is None:
        context = CallbackContext()

    if isinstance(obj, dict):
        context.processed_objects += 1
        for key, value in obj.items():
            if append_slash_func:
                key = append_slash_func(key)
            advanced_json_traversal(value, callback_func, append_slash_func, context)

    elif isinstance(obj, list):
        context.processed_arrays += 1
        for item in obj:
            advanced_json_traversal(item, callback_func, append_slash_func, context)

    else:
        callback_func(context, obj)

# Define the generate_socket_connections function
def generate_socket_connections(num_connections):
    statuses = ['Connected', 'Disconnected', 'Error']
    connections = []

    for _ in range(num_connections):
        session_id = random.randint(1000, 9999)
        ip_address = f""192.168.{random.randint(1, 255)}.{random.randint(1, 255)}""
        port_number = random.randint(1024, 65535)
        status = random.choice(statuses)

        socket_address = SOCKET_ADDRESS_T(ip_address, port_number)
        connection_details = SOCKET_CONNECTION_DETAILS_T(status, session_id, socket_address)

        connections.append(connection_details)

    return connections

# Define the json_data structure
