    ""users"": [
        {""name"": ""Alice"", ""age"": 30},
        {""name"": ""Bob"", ""age"": 25}
    ],
    ""services"": {
        ""service1"": {""enabled"": True, ""port"": 8080},
        ""service2"": {""enabled"": False, ""port"": 9090}
    }
}

# Define a simple callback function for demonstration
def print_callback(context, value):
    if isinstance(value, dict) and 'name' in value:
        print(f""Processing user: {value['name']}"")
    elif isinstance(value, int) and context.processed_objects > 0:
        print(f""Age or port number found: {value}"")

# Call advanced_json_traversal with json_data
advanced_json_traversal(json_data, print_callback)

# Generate 5 socket connections and print their details
