import random
import string

class SecurityHeader:
    def __init__(self, header_value):
        self.header_value = header_value

class CipheringInfo:
    def __init__(self, ciphering_key, integrity_protection_key):
        self.ciphering_key = ciphering_key
        self.integrity_protection_key = integrity_protection_key

class SUCI:
    def __init__(self, suci_value):
        self.suci_value = suci_value

class DeviceSpecificNasMessage:
    def __init__(self, security_header, suci, ciphering_info):
        self.security_header = security_header
        self.suci = suci
        self.ciphering_info = ciphering_info

def generate_random_key(length=16):
    return ''.join(random.choices(string.ascii_uppercase + string.digits, k=length))

def create_device_specific_nas_messages(size):
    if size <= 0:
        raise ValueError(""Size must be a positive integer."")

    try:
        messages = []
        for _ in range(size):
            security_header = SecurityHeader(generate_random_key())
            suci = SUCI(generate_random_key(8))
            ciphering_info = CipheringInfo(generate_random_key(), generate_random_key())
            message = DeviceSpecificNasMessage(security_header, suci, ciphering_info)
            messages.append(message)
        return messages
    except MemoryError:
        raise RuntimeError(""Memory allocation failed."")

def validate_message_structure(messages, expected_security_header, expected_suci):
    for msg in messages:
        if (msg.security_header.header_value != expected_security_header or 
                msg.suci.suci_value != expected_suci):
            return False
    return True

def main(size, expected_security_header, expected_suci):
    try:
        messages = create_device_specific_nas_messages(size)

        is_valid = validate_message_structure(messages, expected_security_header, expected_suci)
        if not is_valid:
            raise ValueError(""Validation failed for one or more DeviceSpecificNasMessage structures."")

        print(f""All {size} DeviceSpecificNasMessage structures are valid."")

    except Exception as e:
        print(f""Error: {str(e)}"")

if __name__ == ""__main__"":
    # Example usage
    main(5, ""EXPECTED_HEADER"", ""EXPECTED_SUCI"")
