import argparse
import os
import re

def summarize_file(file_path):
    try:
        with open(file_path, 'r') as file:
            content = file.read()
            return {'total_chars': len(content), 'total_words': len(content.split()), 'total_lines': content.count('\n') + 1}
    except FileNotFoundError:
        raise ValueError(f""File '{file_path}' not found."")

def count_unique_words(file_path):
    try:
        with open(file_path, 'r') as file:
            content = file.read().lower()
            words = re.findall(r'\b\w+\b', content)
            return len(set(words))
    except FileNotFoundError:
        raise ValueError(f""File '{file_path}' not found."")

def handle_options(args):
    parser = argparse.ArgumentParser(description='File Analysis Tool')
    parser.add_argument('input_file', help='Path to the input file')
    parser.add_argument('-s', action='store_true', help='Summarize the contents of the file')
    parser.add_argument('-l', action='store_true', help='Count unique words in the file')
    parser.add_argument('-o', dest='output_file', help='Redirect output to a specified file')

    parsed_args = parser.parse_args(args)

    if not (parsed_args.s or parsed_args.l):
        print(""Please specify an operation: -s for summary, -l for counting unique words."")
        return

    try:
        input_file_path = parsed_args.input_file
        output_file_path = parsed_args.output_file

        results = []

        if parsed_args.s:
            summary = summarize_file(input_file_path)
            results.append(f""Summary:\nTotal Characters: {summary['total_chars']}\nTotal Words: {summary['total_words']}\nTotal Lines: {summary['total_lines']}"")

        if parsed_args.l:
            unique_word_count = count_unique_words(input_file_path)
            results.append(f""Unique Word Count: {unique_word_count}"")

        output_content = ""\n"".join(results)

        if output_file_path:
            with open(output_file_path, 'w') as out_file:
                out_file.write(output_content)
            print(f""Output written to '{output_file_path}'"")
        else:
            print(output_content)

    except Exception as e:
        print(f""Error: {e}"")

if __name__ == '__main__':
    import sys
    handle_options(sys.argv[1:])
