def validate_nmi_structures(nmi_structures: List[Dict[str, Any]]) -> bool:
    seen_sender_pid = set()

    for structure in nmi_structures:
        header = structure.get('NMI_HEADER', {})
        sender_pid = header.get('Sender_PID')

        if not sender_pid or sender_pid in seen_sender_pid:
            return False
        seen_sender_pid.add(sender_pid)

        parameters_list = structure.get('Parameters_list', [])
        for param in parameters_list:
            if 'value' not in param or 'data_type' not in param:
                return False

        event_records_array = structure.get('Event_Records_array', [])
        event_ids = [event['event_id'] for event in event_records_array]
        if len(event_ids) != len(set(event_ids)):
            return False

    return True

# Example usage
