    def random_sri():
        # Assuming SRIs are similar in structure to RAI
        country_code = random.randint(1, 999)
        location_area_code = f""{random.randint(0, 9)}{random.randint(0, 9)}{random.randint(0, 9)}""
        cell_identity = f""{random.randint(0, 9)}{random.choices(string.digits, k=8)}""
        return f""{country_code:03d}{location_area_code:09d}{cell_identity:09d}""

    structures = []

    for _ in range(n):
        structure = {
            ""IMEI"": random_imei(),
            ""IMSI"": random_imsi(),
            ""TAC"": random_tac(),
            ""RAI"": random_rai(),
            ""SRI"": random_sri()
        }
        structures.append(structure)

    return structures
