import os
import requests
import threading
from concurrent.futures import ThreadPoolExecutor
from datetime import datetime
import logging
import csv
from fpdf import FPDF

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

API_KEY = 'YOUR_ALPHA_VANTAGE_API_KEY'  # Replace with your Alpha Vantage API key
BASE_URL = ""https://www.alphavantage.co/query""

def fetch_stock_data(symbol, function, interval=""1min"", outputsize=""compact""):
    try:
        params = {
            ""function"": function,
            ""symbol"": symbol,
            ""interval"": interval if function == ""TIME_SERIES_INTRADAY"" else None,
            ""outputsize"": outputsize,
            ""apikey"": API_KEY
        }
        response = requests.get(BASE_URL, params=params)
        response.raise_for_status()
        return response.json()
    except requests.exceptions.HTTPError as http_err:
        logging.error(f'HTTP error occurred: {http_err}')
    except Exception as err:
        logging.error(f'Other error occurred: {err}')

def fetch_data_in_parallel(symbols, function):
    with ThreadPoolExecutor() as executor:
        results = list(executor.map(lambda sym: fetch_stock_data(sym, function), symbols))
    return dict(zip(symbols, results))

def parse_real_time_data(data):
    report = []
    for symbol, content in data.items():
        try:
            result = content.get(""Time Series (1min)"", {})
            if not result:
                continue
            latest_time = next(iter(result))
            stock_info = {
                ""Symbol"": symbol,
                ""Price"": result[latest_time][""4. close""],
                ""Volume"": None,  # Alpha Vantage does not provide volume in intraday data
                ""Market Cap"": None  # Fetch separately or from another API endpoint if available
            }
            report.append(stock_info)
        except Exception as e:
            logging.error(f""Error parsing real-time data for {symbol}: {e}"")
    return report

def parse_historical_data(data, symbol):
    try:
        time_series = data.get(""Time Series (Daily)"", {})
        historical_prices = {
            ""Symbol"": symbol,
            ""Data"": [(date, info[""4. close""]) for date, info in time_series.items()]
        }
        return historical_prices
    except Exception as e:
        logging.error(f""Error parsing historical data for {symbol}: {e}"")

def save_report_to_csv(report_data, filename=""stock_report.csv""):
    with open(filename, mode='w', newline='') as file:
        writer = csv.DictWriter(file, fieldnames=report_data[0].keys())
        writer.writeheader()
        for row in report_data:
            writer.writerow(row)
    logging.info(f""Report saved to {filename}"")

def save_report_to_pdf(report_data, filename=""stock_report.pdf""):
    pdf = FPDF()
    pdf.add_page()
    pdf.set_font(""Arial"", size=12)

    for symbol_info in report_data:
        pdf.cell(200, 10, txt=f'Symbol: {symbol_info[""Symbol""]}', ln=True)
        pdf.cell(200, 10, txt=f'Price: {symbol_info[""Price""]}', ln=True)
        if ""Data"" in symbol_info:
            pdf.ln()
            pdf.cell(200, 10, txt=""Historical Prices:"", ln=True)
            for date, price in symbol_info[""Data""]:
                pdf.cell(200, 10, txt=f'{date}: {price}', ln=True)

    pdf.output(filename)
    logging.info(f""Report saved to {filename}"")

def get_user_input():
    while True:
        user_input = input(""Enter company symbols separated by commas or type 'exit' to quit: "").strip()
        if user_input.lower() == 'exit':
            return None
        symbols = [symbol.strip().upper() for symbol in user_input.split("","") if symbol.strip()]
        return symbols

def main():
    while True:
        symbols = get_user_input()
        if not symbols:
            break

        print(""Choose an option:"")
        print(""1. View Current Prices"")
        print(""2. View Historical Data"")
        print(""3. Exit"")

        choice = input(""Enter your choice: "")

        if choice == '1':
            data = fetch_data_in_parallel(symbols, ""TIME_SERIES_INTRADAY"")
            report = parse_real_time_data(data)
            for entry in report:
                logging.info(entry)
            save_report_to_csv(report)

        elif choice == '2':
            print(""Enter date range (YYYY-MM-DD) or predefined intervals (1mo, 3mo, 6mo): "")
            period = input(""Enter your choice: "").strip().lower()
            interval_map = {""1mo"": ""1m"", ""3mo"": ""3m"", ""6mo"": ""6m""}
            interval = interval_map.get(period, ""compact"")

            data = fetch_data_in_parallel(symbols, ""TIME_SERIES_DAILY"" if period in interval_map else ""DIGITAL_CURRENCY_DAILY"")
            historical_reports = []
            for symbol in symbols:
                historical_report = parse_historical_data(data[symbol], symbol)
                if historical_report:
                    historical_reports.append(historical_report)

            for entry in historical_reports:
                logging.info(entry)

            save_report_to_pdf(historical_reports)

        elif choice == '3':
            break

if __name__ == ""__main__"":
    main()
