import random
import string

class DEVICE_REGISTRATION_ACCEPT:
    def __init__(self, IMEI, IMSI, TAC, RAI, SRI):
        self.IMEI = IMEI
        self.IMSI = IMSI
        self.TAC = TAC
        self.RAI = RAI
        self.SRI = SRI

def generate_device_registration_accepts(n):
    def random_imei():
        return ''.join(random.choices(string.digits, k=15))

    def random_imsi():
        return '310' + ''.join(random.choices(string.digits, k=13))  # Example for USA

    def random_tac():
        return ''.join(random.choices(string.digits, k=3))

    def random_rai():
        return ''.join(random.choices(string.hexdigits.upper(), k=6))

    def random_sri():
        return ''.join(random.choices(string.hexdigits.upper(), k=2))

    devices = []
    for _ in range(n):
        imei = random_imei()
        imsi = random_imsi()
        tac = random_tac()
        rai = random_rai()
        sri = random_sri()
        device = DEVICE_REGISTRATION_ACCEPT(IMEI=imei, IMSI=imsi, TAC=tac, RAI=rai, SRI=sri)
        devices.append(device)

    return devices

# Example usage:
# print(generate_device_registration_accepts(5))
