import random
import string

class DeviceRegistrationAccept:
    def __init__(self, imei, imsi, tac, rai, sri):
        self.imei = imei
        self.imsi = imsi
        self.tac = tac
        self Rai = rai
        self SRI = sri

def generate_random_imei():
    return ''.join(random.choices(string.digits, k=15))

def generate_random_imsi():
    country_code = ''.join(random.choices(string.digits, k=3))
    network_code = ''.join(random.choices(string.digits, k=5))
    mobile_id = ''.join(random.choices(string.digits, k=7))
    return f""{country_code}{network_code}{mobile_id}""

def generate_random_tac():
    return ''.join(random.choices(string.digits, k=3))

def generate_random_rai():
    return ''.join(random.choices(string.digits, k=6))

def generate_random_sri():
    return ''.join(random.choices(string.digits, k=4))

def create_device_registration_accept_list(n):
    device_list = []
    for _ in range(n):
        imei = generate_random_imei()
        imsi = generate_random_imsi()
        tac = generate_random_tac()
        rai = generate_random_rai()
        sri = generate_random_sri()

        device = DeviceRegistrationAccept(imei, imsi, tac, rai, sri)
        device_list.append(device)
    return device_list

